CREATE TABLE site (
    name TEXT NOT NULL,
    prefix TEXT NOT NULL,
    created_at TEXT NOT NULL,
    PRIMARY KEY (name)
);
CREATE TABLE batches (
    name TEXT PRIMARY KEY,
    created_at TEXT NOT NULL,
    closed_at TEXT NULL
);
CREATE TABLE hands (
    id TEXT PRIMARY KEY,
    kind TEXT NOT NULL,
    last_seen TEXT NULL,
    CHECK (kind IN ('claude', 'copilot', 'human'))
);
CREATE TABLE ticket_labels (
    ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    label TEXT NOT NULL,
    PRIMARY KEY (ticket_id, label)
);
CREATE TABLE links (
    from_ticket TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    to_ticket   TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    PRIMARY KEY (from_ticket, to_ticket, kind),
    CHECK (kind IN ('blocks', 'related'))
);
CREATE TABLE events (
    id BLOB PRIMARY KEY,
    at TEXT NOT NULL,
    kind TEXT NOT NULL,
    ticket TEXT NULL REFERENCES tickets(id) ON DELETE SET NULL,
    body TEXT NOT NULL DEFAULT ''
, scope_kind TEXT NOT NULL
    DEFAULT 'site'
    CHECK (scope_kind IN ('ticket','batch','hand','worktree','site')), scope_batch TEXT NULL
    REFERENCES batches(name), scope_hand TEXT NULL
    REFERENCES hands(id), scope_run_id TEXT NULL);
CREATE TABLE foreman (
    site TEXT PRIMARY KEY REFERENCES site(name) ON DELETE CASCADE,
    pid INTEGER NULL,
    started_at TEXT NULL
, mode TEXT NOT NULL DEFAULT 'stopped'
  CHECK (mode IN ('stopped', 'detached', 'attached')));
CREATE TABLE worktrees (
    run_id TEXT PRIMARY KEY,
    branch TEXT NOT NULL,
    path TEXT NOT NULL,
    created_at TEXT NOT NULL,
    closed_at TEXT NULL
);
CREATE INDEX idx_ticket_labels_label ON ticket_labels(label, ticket_id);
CREATE INDEX idx_links_to ON links(to_ticket);
CREATE INDEX idx_events_at ON events(at);
CREATE INDEX idx_events_ticket ON events(ticket);
CREATE INDEX idx_worktrees_branch ON worktrees(branch);
CREATE TABLE IF NOT EXISTS "tickets" (
    id TEXT PRIMARY KEY,
    batch TEXT NULL REFERENCES batches(name),
    ordinal INTEGER NULL,
    title TEXT NOT NULL,
    body TEXT NOT NULL DEFAULT '',
    state TEXT NOT NULL,
    owner TEXT NULL REFERENCES hands(id),
    merge_sha TEXT NULL,
    block_reason TEXT NULL,
    block_reason_detail TEXT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CHECK (state IN ('ready', 'in_flight', 'in_review',
                     'blocked', 'done', 'rejected')),
    CHECK (block_reason IS NULL OR
           block_reason IN ('dependency', 'pr_closed_unmerged',
                            'restack_conflict', 'human')),
    CHECK ((state = 'blocked') = (block_reason IS NOT NULL)),
    CHECK (ordinal IS NULL OR batch IS NOT NULL)
);
CREATE INDEX idx_tickets_state ON tickets(state);
CREATE INDEX idx_tickets_batch_ordinal ON tickets(batch, ordinal);
CREATE INDEX idx_tickets_owner ON tickets(owner);
CREATE INDEX idx_events_scope_kind ON events(scope_kind);
CREATE INDEX idx_events_scope_batch ON events(scope_batch);
CREATE INDEX idx_events_scope_hand  ON events(scope_hand);

